        groups.append(g)
        group_map[g] = {'count': 0, 'units': 0, 'net': 0}
    group_map[g]['count'] += 1
    group_map[g]['units'] += row['qty']
    group_map[g]['net'] += row['qty'] * row['price'] - row['discount']
